def json_dumps(item, default_mapping=None, force_use_builtin_json: bool=False, **kwargs):
    if orjson is not None and not force_use_builtin_json:
        if kwargs:
            raise TypeError('orjson does not accept the sort_keys parameter.' if 'sort_keys' in kwargs else 'orjson does not accept additional parameters.')
        return orjson.dumps(item, default=json_convertor_default(default_mapping)).decode('utf-8')
    else:
        return json.dumps(item, default=json_convertor_default(default_mapping), **kwargs)

def to_json_pickle(self):
    try:
        import jsonpickle
        copied = self.copy()
        return jsonpickle.encode(copied)
    except ImportError:
        logger.error('jsonpickle library needs to be installed in order to run to_json_pickle')

def to_json(self, default_mapping: Optional[dict]=None, force_use_builtin_json=False, **kwargs):
    dic = self.to_dict(view_override=TEXT_VIEW)
    return json_dumps(
        dic,
        default_mapping=default_mapping,
        force_use_builtin_json=force_use_builtin_json,
        **kwargs,
    )

